    protected override async Task OnInitializedAsync()
    {
        ReadUrlParameters();
        _searchFilterInput = _searchFilter;
        await LoadDataAsync();
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (_pendingShowCreate && _createDialog is not null)
        {
            await _createDialog.ShowAsync().ConfigureAwait(false);
            _pendingShowCreate = false;
        }

        if (_pendingShowDisable && _disableDialog is not null)
        {
            await _disableDialog.ShowAsync().ConfigureAwait(false);
            _pendingShowDisable = false;
        }

        if (_pendingShowEnable && _enableDialog is not null)
        {
            await _enableDialog.ShowAsync().ConfigureAwait(false);
            _pendingShowEnable = false;
        }

        if (_pendingShowAddUser && _addUserDialog is not null)
        {
            await _addUserDialog.ShowAsync().ConfigureAwait(false);
            _pendingShowAddUser = false;
        }

        if (_pendingShowRemoveUser && _removeUserDialog is not null)
        {
            await _removeUserDialog.ShowAsync().ConfigureAwait(false);
            _pendingShowRemoveUser = false;
        }

        if (_pendingShowChangeRole && _changeRoleDialog is not null)
        {
            await _changeRoleDialog.ShowAsync().ConfigureAwait(false);
            _pendingShowChangeRole = false;
        }
    }

    private async Task LoadDataAsync()
    {
        _loadCts?.Cancel();
        _loadCts?.Dispose();
        _loadCts = new CancellationTokenSource();
        CancellationToken ct = _loadCts.Token;

        _isLoading = _tenants is null;
        try
        {
            IReadOnlyList<TenantSummary> result = await TenantApi
                .ListTenantsAsync(ct)
                .ConfigureAwait(false);
            _tenants = result;
            UpdateFilteredTenants();
            _apiUnavailable = false;
            _apiErrorMessage = "The admin backend service may be unavailable. Check DAPR sidecar connectivity.";
        }
        catch (OperationCanceledException)
        {
            return;
        }
        catch (UnauthorizedAccessException)
        {
            _apiUnavailable = true;
            _apiErrorMessage = "Authentication required. Please sign in again.";
        }
        catch (ForbiddenAccessException)
        {
            _apiUnavailable = true;
            _apiErrorMessage = "Access denied. Insufficient permissions to view tenants.";
        }
        catch (HttpRequestException ex)
        {
            _apiUnavailable = true;
            _apiErrorMessage = $"Unable to load tenant data ({(int?)ex.StatusCode ?? 0}).";
        }
        catch (ServiceUnavailableException)
        {
            _apiUnavailable = true;
            _apiErrorMessage = "Tenants service is not responding. Tenant data may be stale or unavailable.";
        }
        finally
        {
            _isLoading = false;
            _showCreateAction = _tenants is not null && _tenants.Count == 0;
            await InvokeAsync(StateHasChanged);
        }
    }

    private void UpdateFilteredTenants()
    {
        IEnumerable<TenantSummary> filtered = _tenants ?? [];

        if (_statusFilterInput != "All" && Enum.TryParse<TenantStatusType>(_statusFilterInput, out TenantStatusType statusFilter))
        {
            filtered = filtered.Where(t => t.Status == statusFilter);
        }

        if (!string.IsNullOrWhiteSpace(_searchFilter))
        {
            string search = _searchFilter.Trim();
            filtered = filtered.Where(t =>
                t.TenantId.StartsWith(search, StringComparison.OrdinalIgnoreCase)
                || t.Name.StartsWith(search, StringComparison.OrdinalIgnoreCase));
        }

        _filteredTenants = filtered.ToList();
    }

    private async Task OnManualRefresh() => await LoadDataAsync();

    private void OnStatusFilterChanged()
    {
        UpdateFilteredTenants();
        UpdateUrl();
        StateHasChanged();
    }

    private void OnSearchFilterChanged()
    {
        _debounceTimer?.Change(Timeout.Infinite, Timeout.Infinite);
        _debounceTimer?.Dispose();
        _debounceTimer = new Timer(OnDebounceElapsed, null, 300, Timeout.Infinite);
    }

    private void OnDebounceElapsed(object? state)
    {
        if (_disposed) { return; }
        _ = InvokeAsync(() =>
        {
            if (_disposed) { return; }
            _searchFilter = string.IsNullOrWhiteSpace(_searchFilterInput) ? null : _searchFilterInput.Trim();
            UpdateFilteredTenants();
            UpdateUrl();
            StateHasChanged();
        });
    }

    private void ReadUrlParameters()
    {
        Uri uri = NavigationManager.ToAbsoluteUri(NavigationManager.Uri);
        System.Collections.Specialized.NameValueCollection query = System.Web.HttpUtility.ParseQueryString(uri.Query);
        string? status = query["status"];
        if (!string.IsNullOrEmpty(status) && Enum.TryParse<TenantStatusType>(status, out _))
        {
            _statusFilterInput = status;
        }

        _searchFilter = query["search"];
    }

    private void UpdateUrl()
    {
        List<string> queryParams = [];
        if (_statusFilterInput != "All")
        {
            queryParams.Add($"status={Uri.EscapeDataString(_statusFilterInput)}");
        }

        if (!string.IsNullOrEmpty(_searchFilter))
        {
            queryParams.Add($"search={Uri.EscapeDataString(_searchFilter)}");
        }

        string url = queryParams.Count > 0 ? $"/tenants?{string.Join('&', queryParams)}" : "/tenants";
        NavigationManager.NavigateTo(url, forceLoad: false, replace: true);
    }

    // ---- Row click / detail panel ----
    private async Task OnRowClick(TenantSummary? tenant)
    {
        if (tenant is null) { return; }

        if (_expandedTenantId == tenant.TenantId)
        {
            _expandedTenantId = null;
            _expandedDetail = null;
            _expandedUsers = [];
            return;
        }

        _detailCts?.Cancel();
        _detailCts?.Dispose();
        _detailCts = new CancellationTokenSource();
        CancellationToken ct = _detailCts.Token;

        _expandedTenantId = tenant.TenantId;
        _expandedDetail = null;
        _expandedUsers = [];
        _usersUnavailable = false;
        _isLoadingDetail = true;
        StateHasChanged();

        try
        {
            Task<TenantDetail?> detailTask = TenantApi.GetTenantDetailAsync(tenant.TenantId, ct);
            Task<IReadOnlyList<TenantUser>> usersTask = TenantApi.GetTenantUsersAsync(tenant.TenantId, ct);

            try
            {
                _expandedDetail = await detailTask.ConfigureAwait(false);
            }
            catch (OperationCanceledException) { throw; }
            catch (Exception)
            {
                // Detail load failed — shows fallback message
            }

            try
            {
                _expandedUsers = await usersTask.ConfigureAwait(false);
            }
            catch (OperationCanceledException) { throw; }
            catch (Exception)
            {
                _expandedUsers = [];
                _usersUnavailable = true;
            }
        }
        catch (OperationCanceledException)
        {
            return;
        }
        finally
        {
            _isLoadingDetail = false;
            await InvokeAsync(StateHasChanged);
        }
    }

    // ---- Status badge helper ----
    private static (BadgeAppearance Appearance, string CssClass) GetStatusBadge(TenantStatusType status) =>
        status switch
        {
            TenantStatusType.Active => (BadgeAppearance.Filled, "tenant-status-active"),
            TenantStatusType.Disabled => (BadgeAppearance.Filled, "tenant-status-disabled"),
            _ => (BadgeAppearance.Filled, ""),
        };

    private static string GetTenantLifecycleFocusId(string action, string tenantId)
        => $"tenant-{action}-{Uri.EscapeDataString(tenantId)}";

    private string GetTenantUserFocusId(string action, string userId)
        => $"tenant-{action}-{Uri.EscapeDataString(_expandedTenantId ?? string.Empty)}-{Uri.EscapeDataString(userId)}";

    // ---- Create Tenant ----
    private void OpenCreateDialog()
    {
        if (_isAnyDialogOpen) { return; }
        _createTenantId = string.Empty;
        _createName = string.Empty;
        _createDescription = string.Empty;
        _initiatorId = "tenant-create-button";
        _showCreateDialog = true;
        _pendingShowCreate = true;
    }

    private async Task CloseCreateDialogAsync()
    {
        if (_createDialog is not null)
        {
            await _createDialog.HideAsync().ConfigureAwait(false);
        }

        _showCreateDialog = false;
        await RestoreInitiatorFocusAsync().ConfigureAwait(false);
    }

    private bool IsCreateFormValid()
        => !string.IsNullOrWhiteSpace(_createTenantId) && IsValidTenantId(_createTenantId) && !string.IsNullOrWhiteSpace(_createName);

    private static bool IsValidTenantId(string? id)
        => !string.IsNullOrWhiteSpace(id) && TenantIdRegex.IsMatch(id);

    private async Task OnCreateTenantConfirm()
    {
        string confirmationTarget = Text["TenantTarget", _createTenantId ?? string.Empty];
        if (!ConfirmationFacts.IsExactAndSupportSafe(confirmationTarget))
        {
            await ToastService.ShowErrorAsync(Text["ConfirmationUnsafeTarget"]).ConfigureAwait(false);
            await CloseCreateDialogAsync().ConfigureAwait(false);
            return;
        }

        _isOperating = true;
        StateHasChanged();
        _operationCts?.Cancel();
        _operationCts?.Dispose();
        _operationCts = new CancellationTokenSource();

        try
        {
            AdminOperationResult? createResult;
            try
            {
                string? description = string.IsNullOrWhiteSpace(_createDescription) ? null : _createDescription.Trim();
                createResult = await TenantApi.CreateTenantAsync(
                    new CreateTenantRequest(_createTenantId!.Trim(), _createName!.Trim(), description),
                    _operationCts.Token).ConfigureAwait(false);
            }
            catch (OperationCanceledException)
            {
                return;
            }
            catch (ServiceUnavailableException)
            {
                await ToastService.ShowErrorAsync("Tenants service unavailable. Try again later.").ConfigureAwait(false);
                return;
            }
            catch (UnauthorizedAccessException)
            {
                await ToastService.ShowErrorAsync("Authentication required. Please sign in again.").ConfigureAwait(false);
                await CloseCreateDialogAsync().ConfigureAwait(false);
                return;
            }
            catch (ForbiddenAccessException)
            {
                await ToastService.ShowErrorAsync("Access denied. Administrator permission is required.").ConfigureAwait(false);
                await CloseCreateDialogAsync().ConfigureAwait(false);
                return;
            }
            catch (Exception ex)
            {
                _ = ex;
                await ToastService.ShowErrorAsync("Failed to create tenant.").ConfigureAwait(false);
                return;
            }

            if (createResult?.Success != true)
            {
                await ToastService.ShowErrorAsync(createResult?.Message ?? "Failed to create tenant.").ConfigureAwait(false);
                return;
            }

            try
            {
                await ToastService.ShowSuccessAsync($"Create request accepted for tenant {_createTenantId}; refresh to confirm completion.").ConfigureAwait(false);
                if (_createDialog is not null)
                {
                    await _createDialog.HideAsync().ConfigureAwait(false);
                }

                _showCreateDialog = false;
                await LoadDataAsync().ConfigureAwait(false);
            }
            catch (Exception ex)
            {
                _ = ex;
                _showCreateDialog = false;
                await InvokeAsync(StateHasChanged).ConfigureAwait(false);
                await ToastService.ShowInfoAsync(
                    "Create request was accepted, but the interface refresh failed. Refresh the tenant list before deciding whether to retry.").ConfigureAwait(false);
            }
        }
        finally
        {
            _isOperating = false;
            await InvokeAsync(StateHasChanged);
        }
    }

