    private async Task CloseLifecycleDialogAsync()
    {
        // Only hide the dialog that is actually open — avoids calling HideAsync on a null/unrendered ref.
        if (_showDisableDialog && _disableDialog is not null)
        {
            await _disableDialog.HideAsync().ConfigureAwait(false);
        }
        else if (_showEnableDialog && _enableDialog is not null)
        {
            await _enableDialog.HideAsync().ConfigureAwait(false);
        }

        _showDisableDialog = false;
        _showEnableDialog = false;
        _lifecycleTarget = null;
        await RestoreInitiatorFocusAsync().ConfigureAwait(false);
    }

    private async Task OnDisableConfirm()
    {
        if (_lifecycleTarget is null) { return; }
        if (!ConfirmationFacts.IsExactAndSupportSafe(Text["TenantTarget", _lifecycleTarget.TenantId]))
        {
            await ToastService.ShowErrorAsync(Text["ConfirmationUnsafeTarget"]).ConfigureAwait(false);
            await CloseLifecycleDialogAsync().ConfigureAwait(false);
            return;
        }

        await ExecuteLifecycleAction(
            ct => TenantApi.DisableTenantAsync(_lifecycleTarget.TenantId, ct),
            "Disable",
            "Failed to disable tenant.");
    }

    private async Task OnEnableConfirm()
    {
        if (_lifecycleTarget is null) { return; }
        if (!ConfirmationFacts.IsExactAndSupportSafe(Text["TenantTarget", _lifecycleTarget.TenantId]))
        {
            await ToastService.ShowErrorAsync(Text["ConfirmationUnsafeTarget"]).ConfigureAwait(false);
            await CloseLifecycleDialogAsync().ConfigureAwait(false);
            return;
        }

        await ExecuteLifecycleAction(
            ct => TenantApi.EnableTenantAsync(_lifecycleTarget.TenantId, ct),
            "Enable",
            "Failed to enable tenant.");
    }

    private async Task ExecuteLifecycleAction(Func<CancellationToken, Task<AdminOperationResult?>> action, string actionName, string failMsg)
    {
        _isOperating = true;
        StateHasChanged();
        _operationCts?.Cancel();
        _operationCts?.Dispose();
        _operationCts = new CancellationTokenSource();

        try
        {
            AdminOperationResult? result = await action(_operationCts.Token);
            if (result?.Success == true)
            {
                await ToastService.ShowInfoAsync(
                    $"{actionName} request accepted; final tenant status is unknown until the tenant list confirms it. Refresh to check status. Operation ID: {result.OperationId}.");
                await CloseLifecycleDialogAsync().ConfigureAwait(false);
                await LoadDataAsync();
            }
            else
            {
                await ToastService.ShowErrorAsync(result?.Message ?? failMsg);
            }
        }
        catch (ServiceUnavailableException ex)
        {
            await ToastService.ShowErrorAsync(ex.Message);
        }
        catch (UnauthorizedAccessException)
        {
            await ToastService.ShowErrorAsync("Authentication required. Please sign in again.").ConfigureAwait(false);
            await CloseLifecycleDialogAsync().ConfigureAwait(false);
        }
        catch (ForbiddenAccessException)
        {
            await ToastService.ShowErrorAsync("Access denied. Administrator permission is required.").ConfigureAwait(false);
            await CloseLifecycleDialogAsync().ConfigureAwait(false);
        }
        catch (Exception ex)
        {
            _ = ex;
            await ToastService.ShowErrorAsync(failMsg).ConfigureAwait(false);
        }
        finally
        {
            _isOperating = false;
            await InvokeAsync(StateHasChanged);
        }
    }

