                await ToastService.ShowSuccessAsync($"Change-role request accepted for {_changeRoleTarget.UserId}; refresh to confirm completion.").ConfigureAwait(false);
                if (_changeRoleDialog is not null)
                {
                    await _changeRoleDialog.HideAsync().ConfigureAwait(false);
                }

                _showChangeRoleDialog = false;
                _changeRoleTarget = null;
                await ReloadDetailPanel();
            }
            else
            {
                await ToastService.ShowErrorAsync(result?.Message ?? "Failed to change role.");
            }
        }
        catch (UnauthorizedAccessException)
        {
            await ToastService.ShowErrorAsync("Authentication required. Please sign in again.").ConfigureAwait(false);
            await CloseChangeRoleDialogAsync().ConfigureAwait(false);
        }
        catch (ForbiddenAccessException)
        {
            await ToastService.ShowErrorAsync("Access denied. Administrator permission is required.").ConfigureAwait(false);
            await CloseChangeRoleDialogAsync().ConfigureAwait(false);
        }
        catch (Exception ex)
        {
            _ = ex;
            await ToastService.ShowErrorAsync("Failed to change role.").ConfigureAwait(false);
        }
        finally
        {
            _isOperating = false;
            await InvokeAsync(StateHasChanged);
        }
    }

    private async Task ReloadDetailPanel()
    {
        if (_expandedTenantId is null) { return; }
        try
        {
            _expandedUsers = await TenantApi.GetTenantUsersAsync(_expandedTenantId).ConfigureAwait(false);
        }
        catch (Exception)
        {
            // Ignore — keeps existing data
        }
        await InvokeAsync(StateHasChanged);
    }

    private async Task RestoreInitiatorFocusAsync()
    {
        string? focusId = _initiatorId;
        _initiatorId = null;
        await InvokeAsync(StateHasChanged).ConfigureAwait(false);
        await FocusService.RestoreAsync(focusId).ConfigureAwait(false);
    }

    // ---- Cleanup ----
    public ValueTask DisposeAsync()
    {
        _disposed = true;
        _loadCts?.Cancel();
        _loadCts?.Dispose();
        _operationCts?.Cancel();
        _operationCts?.Dispose();
        _detailCts?.Cancel();
        _detailCts?.Dispose();
        _debounceTimer?.Dispose();
        return ValueTask.CompletedTask;
    }

